// ─── IMPACT + NAME LOOKUP ─────────────────────────────────────
// `impact` is 'high' for moves with a flight phase / landing (jumps, burpees,
// jacks, skaters, high knees). Entries above that don't say so are 'low'.
// Rules enforced by tests/content.test.js: nothing beginner-tagged is
// high-impact, and every easier variant is beginner-safe.
Object.values(DB).forEach(list => list.forEach(ex => { if (ex.impact !== 'high') ex.impact = 'low'; }));

const EX_BY_NAME = new Map();
Object.entries(DB).forEach(([group, list]) => list.forEach(ex => {
  const k = ex.name.toLowerCase();
  if (!EX_BY_NAME.has(k)) EX_BY_NAME.set(k, { ex, group });
}));

/** { ex, group } for a library exercise name (case-insensitive), or null. */
function exFind(name) {
  return name ? EX_BY_NAME.get(String(name).trim().toLowerCase()) || null : null;
}

// Fallback for custom moves and free-text variants that aren't in the library.
const HIGH_IMPACT_NAME_RE = /\bjump|burpee|\bhops?\b|\bbounds?\b|\bbounding\b|plyo|sprint|skater jump|high knees?\b(?!\s*march)|plank jacks?\b|star jumps?\b|depth (?:drop|jump)|\bclap\b|tuck jump|split jump/i;
const LOW_IMPACT_HINT_RE  = /step[- ]?(?:out|back|jack|through)|no[- ]jump|low[- ]impact|march/i;

/** 'high' | 'low' for an exercise object or a plain move name. */
function exImpact(exOrName) {
  if (!exOrName) return 'low';
  const isObj = typeof exOrName === 'object';
  if (isObj && (exOrName.impact === 'high' || exOrName.impact === 'low')) return exOrName.impact;
  const name = isObj ? exOrName.name : exOrName;
  const hit = exFind(name);
  if (hit) return hit.ex.impact;
  const s = String(name || '');
  return HIGH_IMPACT_NAME_RE.test(s) && !LOW_IMPACT_HINT_RE.test(s) ? 'high' : 'low';
}
/** True when a move (object or name) has a jump / landing. Shared with features.js. */
function exIsHighImpact(exOrName) { return exImpact(exOrName) === 'high'; }

